## OR-Set Implementation Sketch
```swift
struct ORSet<T: Hashable> {
    private var adds: [T: VectorClock] = [:]
    private var removes: [T: VectorClock] = [:]

    mutating func add(_ element: T, clock: VectorClock) {
        adds[element] = clock
    }

    mutating func remove(_ element: T, clock: VectorClock) {
        removes[element] = clock
    }

    func lookup(_ element: T) -> Bool {
        guard let addClock = adds[element] else { return false }
        guard let removeClock = removes[element] else { return true }
        return addClock > removeClock
    }

    func merge(with other: ORSet<T>) -> ORSet<T> {
        var result = self
        for (elem, clock) in other.adds {
            result.adds[elem] = max(result.adds[elem] ?? [:], clock)
        }
        for (elem, clock) in other.removes {
            result.removes[elem] = max(result.removes[elem] ?? [:], clock)
        }
        return result
    }
}
```

## Sync Status View (SwiftUI)
```swift
struct SyncStatusView: View {
    @ObservedObject var syncManager: SyncManager

    var body: some View {
        HStack {
            Image(systemName: syncManager.isOnline ? "wifi" : "wifi.slash")
                .foregroundColor(syncManager.isOnline ? .green : .orange)

            Text(syncManager.isOnline ? "Online" : "Offline")

            Spacer()

            if syncManager.pendingChanges > 0 {
                ProgressView()
                    .scaleEffect(0.8)
                Text("\(syncManager.pendingChanges) pending")
                    .font(.caption)
            } else {
                Image(systemName: "checkmark.circle.fill")
                    .foregroundColor(.green)
            }
        }
        .padding()
    }
}
```

## Why This Is Asked
Tests practical iOS fundamentals: Codable data models, file-based persistence with atomic writes, and SwiftUI data flow. It also exercises UX concerns like debounce for responsiveness and accessibility considerations.

## Key Concepts
- Codable data model for Note with title, body, tags, and date
- File I/O in Documents with atomic write pattern
- SwiftUI state management using @Published and binding for filters
